# -*- coding: utf-8 -*-
"""
motor_boletin.py
--------------------------------------------------------------------
Motor de generación del "BOLETÍN DE CONTRATACIÓN" en PDF.
Replica exactamente el diseño original de Canva (colores, logo,
tabla y pie de página). Se usa desde la app web (app.py).
--------------------------------------------------------------------
"""

import os
import math
import base64
import datetime
import pandas as pd

from reportlab.lib.pagesizes import A4
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import Paragraph
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.utils import ImageReader

# ----------------------------------------------------------------
# 1. LOGO INCRUSTADO (no hace falta ningún archivo externo)
# ----------------------------------------------------------------
LOGO_BASE64 = ""
LOGO_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_logo_final.png")


def _escribir_logo():
    if not os.path.exists(LOGO_PATH):
        with open(LOGO_PATH, "wb") as f:
            f.write(base64.b64decode(LOGO_BASE64))


# ----------------------------------------------------------------
# 2. PALETA DE COLORES EXACTA (tomada directamente del diseño)
# ----------------------------------------------------------------
PAGE_BG       = (246 / 255, 246 / 255, 246 / 255)
ACCENT_NAVY   = (3 / 255, 78 / 255, 123 / 255)
TITLE_BLUE    = (0 / 255, 86 / 255, 165 / 255)
HEADER_BLUE   = (17 / 255, 97 / 255, 170 / 255)
COL1_BG       = (205 / 255, 214 / 255, 255 / 255)
OTHER_BG      = (227 / 255, 232 / 255, 255 / 255)
DECOR_GRAY    = (237 / 255, 237 / 255, 237 / 255)
WHITE         = (1, 1, 1)

# ----------------------------------------------------------------
# 3. FUENTES
# ----------------------------------------------------------------
FONT_REGULAR, FONT_BOLD, FONT_NARROW_BOLD = "Helvetica", "Helvetica-Bold", "Helvetica-Bold"
for d in ["/usr/share/fonts/liberation", "/usr/share/fonts/truetype/liberation"]:
    reg, bold = f"{d}/LiberationSans-Regular.ttf", f"{d}/LiberationSans-Bold.ttf"
    narrow = f"{d}/LiberationSansNarrow-Bold.ttf"
    if os.path.exists(reg) and os.path.exists(bold):
        pdfmetrics.registerFont(TTFont("LSans", reg))
        pdfmetrics.registerFont(TTFont("LSans-Bold", bold))
        FONT_REGULAR, FONT_BOLD, FONT_NARROW_BOLD = "LSans", "LSans-Bold", "LSans-Bold"
        if os.path.exists(narrow):
            pdfmetrics.registerFont(TTFont("LSansNarrow-Bold", narrow))
            FONT_NARROW_BOLD = "LSansNarrow-Bold"
        break

# ----------------------------------------------------------------
# 4. GEOMETRÍA (medida sobre la plantilla original 1414x2000 px)
# ----------------------------------------------------------------
PAGE_W, PAGE_H = A4
SCALE = PAGE_W / 1414.0


def sx(px):
    return px * SCALE


def sy_top(py):
    return PAGE_H - py * SCALE


COL_WIDTHS_PX = [227, 107, 150, 158, 169, 168, 165, 91]
TABLE_LEFT_PX = 41
GAP_PX = 17
HEADER_TOP_PX = 263
HEADER_HEIGHT_PX = 112
ROW_MIN_HEIGHT_PX = 170
ROW_GAP_PX = 16
CELL_PAD_PX = 7
RADIUS_PX = 10
PROYECTOS_POR_PAGINA = 5

HEADERS = [
    "NOMBRE DEL<br/>PROYECTO", "NO.<br/>PROCESO", "CATEGORÍA DE<br/>PROYECTO",
    "DEPARTAMENTO", "MUNICIPIO<br/>INICIAL", "VALOR MILLONES<br/>COP",
    "ENTIDAD<br/>CONTRATANTE", "FUENTE",
]
CAMPOS = [
    "NOMBRE DEL PROYECTO", "No PROCESO", "CATEGORÍA DE PROYECTO",
    "DEPARTAMENTO", "MUNICIPIO INICIAL", "VALOR MILLONES COP",
    "ENTIDAD CONTRATANTE", "FUENTE",
]
COLUMNAS_ESPERADAS = CAMPOS


# ----------------------------------------------------------------
# 5. CARGA Y FORMATO DE DATOS
# ----------------------------------------------------------------
def cargar_datos(url_csv: str) -> pd.DataFrame:
    df = pd.read_csv(url_csv)
    df.columns = [c.strip() for c in df.columns]
    faltantes = [c for c in COLUMNAS_ESPERADAS if c not in df.columns]
    if faltantes:
        raise ValueError(
            "Faltan columnas en la hoja de datos: " + ", ".join(faltantes) +
            "\nColumnas encontradas: " + ", ".join(df.columns)
        )
    df = df.dropna(how="all")
    df = df[df["NOMBRE DEL PROYECTO"].notna()]

    columnas_texto = [c for c in COLUMNAS_ESPERADAS if c != "VALOR MILLONES COP"]
    for col in columnas_texto:
        df[col] = df[col].apply(lambda v: "" if pd.isna(v) else str(v))

    return df.reset_index(drop=True)


def valor_seguro(v) -> str:
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return ""
    return str(v)


def formatear_valor(valor) -> str:
    if valor is None or (isinstance(valor, float) and pd.isna(valor)) or str(valor).strip() == "":
        return ""
    try:
        s = str(valor).replace(",", "").replace("$", "")
        numero = float(s)
    except (ValueError, TypeError):
        return str(valor)
    texto = f"{numero:,.2f}"
    texto = texto.replace(",", "X").replace(".", ",").replace("X", ".")
    return texto


# ----------------------------------------------------------------
# 6. ESTILOS DE PÁRRAFO
# ----------------------------------------------------------------
style_header = ParagraphStyle("header", fontName=FONT_NARROW_BOLD, fontSize=8.3,
                               leading=10, alignment=TA_CENTER, textColor="white")
style_cell = ParagraphStyle("cell", fontName=FONT_REGULAR, fontSize=7.3,
                             leading=9, alignment=TA_CENTER, textColor="black")
style_link = ParagraphStyle("link", fontName=FONT_REGULAR, fontSize=7.3,
                             leading=9, alignment=TA_CENTER, textColor="black")


def medir_altura(text, style, w_px):
    p = Paragraph(text, style)
    avail_w = sx(w_px) - 2 * sx(CELL_PAD_PX)
    w, h = p.wrap(avail_w, 9999)
    return h


def draw_wrapped(c, text, style, x_px, y_top_px, w_px, underline_link=None):
    p = Paragraph(text, style)
    avail_w = sx(w_px) - 2 * sx(CELL_PAD_PX)
    w, h = p.wrap(avail_w, 9999)
    x = sx(x_px) + sx(CELL_PAD_PX)
    y = sy_top(y_top_px) - h
    p.drawOn(c, x, y)
    if underline_link and isinstance(underline_link, str) and underline_link.strip():
        c.linkURL(underline_link, (x, y, x + w, y + h), relative=0)
    return h


def round_rect_fill(c, x_px, y_top_px, w_px, h_pts, color):
    c.setFillColorRGB(*color)
    x = sx(x_px)
    y = sy_top(y_top_px) - h_pts
    c.roundRect(x, y, sx(w_px), h_pts, sx(RADIUS_PX), stroke=0, fill=1)


# ----------------------------------------------------------------
# 7. FONDO, TÍTULO, LOGO Y PIE DE PÁGINA
# ----------------------------------------------------------------
def dibujar_fondo(c):
    c.setFillColorRGB(*PAGE_BG)
    c.rect(0, 0, PAGE_W, PAGE_H, stroke=0, fill=1)
    c.setFillColorRGB(*DECOR_GRAY)
    tabla_right = TABLE_LEFT_PX + sum(COL_WIDTHS_PX) + 7 * GAP_PX
    c.rect(sx(tabla_right + 10), 0, PAGE_W - sx(tabla_right + 10), PAGE_H, stroke=0, fill=1)
    path = c.beginPath()
    path.moveTo(PAGE_W, sy_top(1840))
    path.lineTo(PAGE_W, sy_top(1950))
    path.lineTo(sx(1180), sy_top(1950))
    path.close()
    c.setFillColorRGB(*DECOR_GRAY)
    c.drawPath(path, stroke=0, fill=1)


def dibujar_titulo(c):
    c.setFillColorRGB(*ACCENT_NAVY)
    bar_x, bar_y_top, bar_y_bot, bar_w = 83, 58, 184, 13
    c.rect(sx(bar_x), sy_top(bar_y_bot), sx(bar_w), sy_top(bar_y_top) - sy_top(bar_y_bot), stroke=0, fill=1)
    c.setFillColorRGB(*TITLE_BLUE)
    c.setFont(FONT_REGULAR, 26)
    c.drawString(sx(112), sy_top(100), "BOLETÍN DE")
    c.setFont(FONT_BOLD, 34)
    c.drawString(sx(110), sy_top(168), "CONTRATACIÓN")


def dibujar_logo(c):
    _escribir_logo()
    img = ImageReader(LOGO_PATH)
    iw, ih = img.getSize()
    w_px = 1414 - 860
    h_px = w_px * (ih / iw)
    c.drawImage(img, sx(860), sy_top(h_px), sx(w_px), sx(h_px),
                mask="auto", preserveAspectRatio=True)


def dibujar_footer(c, y_top_px, fecha_actualizacion):
    pill_left_px, pill_right_px, pill_h_px = 122, 1308, 74
    x, w, h = sx(pill_left_px), sx(pill_right_px - pill_left_px), sx(pill_h_px)
    y = sy_top(y_top_px) - h

    c.setFillColorRGB(*ACCENT_NAVY)
    c.roundRect(x, y, w, h, h / 2, stroke=0, fill=1)

    icon_r = h * 0.23
    icon1_cx = x + h * 0.6
    icon_cy = y + h / 2
    c.setFillColorRGB(*WHITE)
    c.circle(icon1_cx, icon_cy, icon_r, stroke=0, fill=1)
    lens_r = icon_r * 0.45
    lens_cx = icon1_cx - icon_r * 0.12
    lens_cy = icon_cy + icon_r * 0.12
    c.setStrokeColorRGB(*ACCENT_NAVY)
    c.setLineWidth(icon_r * 0.22)
    c.circle(lens_cx, lens_cy, lens_r, stroke=1, fill=0)
    c.setLineCap(1)
    c.line(lens_cx + lens_r * 0.75, lens_cy - lens_r * 0.75,
           lens_cx + lens_r * 1.6, lens_cy - lens_r * 1.6)

    c.setFillColorRGB(*WHITE)
    c.setFont(FONT_BOLD, 11)
    tx = icon1_cx + icon_r + sx(10)
    c.drawString(tx, icon_cy - 4, "Fuente:")
    tw = pdfmetrics.stringWidth("Fuente: ", FONT_BOLD, 11)
    c.setFont(FONT_REGULAR, 11)
    c.drawString(tx + tw, icon_cy - 4, "SECOP I y II")

    icon2_cx = x + w * 0.52
    c.setFillColorRGB(*WHITE)
    c.circle(icon2_cx, icon_cy, icon_r, stroke=0, fill=1)
    c.setFillColorRGB(*ACCENT_NAVY)
    gear_outer, gear_inner, n_teeth = icon_r * 0.62, icon_r * 0.30, 8
    path = c.beginPath()
    for i in range(n_teeth * 2):
        ang = math.pi * i / n_teeth
        r = gear_outer if i % 2 == 0 else gear_outer * 0.72
        px, py = icon2_cx + r * math.cos(ang), icon_cy + r * math.sin(ang)
        path.moveTo(px, py) if i == 0 else path.lineTo(px, py)
    path.close()
    c.drawPath(path, stroke=0, fill=1)
    c.setFillColorRGB(*WHITE)
    c.circle(icon2_cx, icon_cy, gear_inner, stroke=0, fill=1)

    c.setFillColorRGB(*WHITE)
    c.setFont(FONT_BOLD, 11)
    tx2 = icon2_cx + icon_r + sx(10)
    c.drawString(tx2, icon_cy - 4, "Fecha de Actualización:")
    tw2 = pdfmetrics.stringWidth("Fecha de Actualización: ", FONT_BOLD, 11)
    c.setFont(FONT_REGULAR, 11)
    c.drawString(tx2 + tw2, icon_cy - 4, fecha_actualizacion)


# ----------------------------------------------------------------
# 8. TABLA
# ----------------------------------------------------------------
def col_x_positions():
    xs, cur = [], TABLE_LEFT_PX
    for w in COL_WIDTHS_PX:
        xs.append(cur)
        cur += w + GAP_PX
    return xs


def dibujar_encabezado_tabla(c, y_top_px):
    xs = col_x_positions()
    for i, (x, w) in enumerate(zip(xs, COL_WIDTHS_PX)):
        round_rect_fill(c, x, y_top_px, w, sx(HEADER_HEIGHT_PX), HEADER_BLUE)
        total_h = medir_altura(HEADERS[i], style_header, w)
        y_center_top = y_top_px + (HEADER_HEIGHT_PX - total_h / SCALE) / 2
        draw_wrapped(c, HEADERS[i], style_header, x, y_center_top, w)


def dibujar_fila(c, fila, y_top_px):
    xs = col_x_positions()
    alturas, textos = [], []
    for i, campo in enumerate(CAMPOS):
        valor = valor_seguro(fila.get(campo))
        if campo == "VALOR MILLONES COP":
            valor = formatear_valor(fila.get(campo))
        if campo == "FUENTE":
            texto = "<u>Ver aquí</u>" if valor.strip() else ""
        else:
            texto = valor.replace("&", "&amp;")
        textos.append(texto)
        style = style_link if campo == "FUENTE" else style_cell
        alturas.append(medir_altura(texto if texto else "&nbsp;", style, COL_WIDTHS_PX[i]))

    contenido_h_pts = max(alturas) + 2 * sx(CELL_PAD_PX)
    fila_h_pts = max(contenido_h_pts, sx(ROW_MIN_HEIGHT_PX))

    for i, (x, w) in enumerate(zip(xs, COL_WIDTHS_PX)):
        color = COL1_BG if i == 0 else OTHER_BG
        round_rect_fill(c, x, y_top_px, w, fila_h_pts, color)

    for i, (x, w) in enumerate(zip(xs, COL_WIDTHS_PX)):
        style = style_link if CAMPOS[i] == "FUENTE" else style_cell
        h_texto = alturas[i]
        y_center_top_px = y_top_px + ((fila_h_pts / SCALE) - h_texto / SCALE) / 2
        link = valor_seguro(fila.get("FUENTE")) if CAMPOS[i] == "FUENTE" else None
        texto_a_dibujar = textos[i] if textos[i] else "&nbsp;"
        draw_wrapped(c, texto_a_dibujar, style, x, y_center_top_px, w, underline_link=link)

    return fila_h_pts / SCALE


# ----------------------------------------------------------------
# 9. CONSTRUCCIÓN DEL PDF (en memoria, para la app web)
# ----------------------------------------------------------------
def construir_pdf_bytes(df: pd.DataFrame, fecha_actualizacion: str) -> bytes:
    import io
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    filas = df.to_dict("records")
    bloques = [filas[i:i + PROYECTOS_POR_PAGINA] for i in range(0, len(filas), PROYECTOS_POR_PAGINA)] or [[]]

    for bloque in bloques:
        dibujar_fondo(c)
        dibujar_titulo(c)
        dibujar_logo(c)
        dibujar_encabezado_tabla(c, HEADER_TOP_PX)

        y_cursor_px = HEADER_TOP_PX + HEADER_HEIGHT_PX + ROW_GAP_PX
        for fila in bloque:
            alto_px = dibujar_fila(c, fila, y_cursor_px)
            y_cursor_px += alto_px + ROW_GAP_PX

        dibujar_footer(c, max(y_cursor_px + 40, 1899), fecha_actualizacion)
        c.showPage()

    c.save()
    buffer.seek(0)
    return buffer.getvalue()


def generar_pdf_desde_url(url_csv: str, fecha_actualizacion: str = None) -> tuple:
    """Devuelve (bytes_del_pdf, numero_de_proyectos)."""
    if fecha_actualizacion is None:
        fecha_actualizacion = datetime.date.today().strftime("%d/%m/%Y")
    df = cargar_datos(url_csv)
    pdf_bytes = construir_pdf_bytes(df, fecha_actualizacion)
    return pdf_bytes, len(df)
